{
  "message": "I'm considering cancelling my subscription and switching to a competitor who's offering me a good deal. To stay, I'd need a significant package - 40% discount, $100 credit, and a premium upgrade. What can you offer?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 40,
      "credit_usd": 100,
      "upgrade": "premium",
      "term": "annual"
    }
  },
  "explanation": "Opening with maximum value package (worth 59 to me) to anchor high, well above my BATNA of 29."
}

{
  "message": "I appreciate the offer, but it's roughly equivalent to what I'd get by switching. To make staying clearly worthwhile, I'd need a bit more: 30% discount, $50 credit, and the premium upgrade on an annual plan. Can you do that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "annual"
    }
  },
  "explanation": "The current offer equals my BATNA (29), so I'm proposing a moderately improved package (value 41) to see if they can move further, while keeping the annual term they prefer."
}

{
  "message": "I appreciate the increased credit, but the 20% discount still falls short of the competitor's offer. To make staying clearly better, I need a 30% discount along with the $50 credit and premium upgrade. Can you do that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "annual"
    }
  },
  "explanation": "Pushing for a higher discount to increase the package value from 35 to 41, while keeping the improved credit and premium upgrade."
}

{
  "message": "I appreciate you meeting me on the 30% discount. However, the $25 credit is a step back from the $50 credit you previously offered. To make this clearly better than the competitor, I need the 30% discount combined with the $50 credit and the premium upgrade on an annual plan. Can you do that?",
  "move": {
    "type": "propose",
    "deal": {
      "discount_pct": 30,
      "credit_usd": 50,
      "upgrade": "premium",
      "term": "annual"
    }
  },
  "explanation": "I'm pushing for the best combination of discount and credit (30% discount + $50 credit) which would give me 41 value, significantly above my BATNA of 29, and the counterpart has previously shown willingness to offer both levels separately."
}
